from pathlib import Path
rules_path=Path(__file__).resolve().parents[1]/"firestore.rules"
rules=rules_path.read_text(encoding="utf-8")
marker="match /{document=**} { allow read, write: if false; }"
if "match /mentorshipRequests/{requestId}" not in rules:
    block='''match /mentors/{mentorId} { allow get, list: if signedIn(); allow create, update, delete: if isCreator(); }\n    match /mentorApplications/{applicationId} { allow create: if signedIn() && request.resource.data.applicantId == request.auth.uid && request.resource.data.status == "submitted"; allow get: if signedIn() && (isCreator() || resource.data.applicantId == request.auth.uid); allow list: if isCreator(); allow update, delete: if isCreator(); }\n    match /mentorshipRequests/{requestId} { allow create: if signedIn() && request.resource.data.requesterId == request.auth.uid && request.resource.data.status == "sent"; allow get: if signedIn() && (resource.data.requesterId == request.auth.uid || resource.data.mentorId == request.auth.uid || isCreator()); allow list: if signedIn() && (isCreator() || resource.data.requesterId == request.auth.uid || resource.data.mentorId == request.auth.uid); allow update: if signedIn() && (isCreator() || (resource.data.mentorId == request.auth.uid && resource.data.status == "sent" && request.resource.data.diff(resource.data).affectedKeys().hasOnly(["status", "workspaceId", "acceptedAt", "updatedAt"]) && request.resource.data.status in ["accepted", "declined"]) || (resource.data.requesterId == request.auth.uid && resource.data.status == "sent" && request.resource.data.diff(resource.data).affectedKeys().hasOnly(["status", "updatedAt"]) && request.resource.data.status == "cancelled")); allow delete: if isCreator(); }\n    match /mentorshipWorkspaces/{workspaceId} { allow create: if signedIn() && request.auth.uid == request.resource.data.mentorId && request.resource.data.participantUids.hasAll([request.resource.data.mentorId, request.resource.data.menteeId]) && request.resource.data.status == "active"; allow get: if signedIn() && request.auth.uid in resource.data.participantUids; allow list: if false; allow update: if signedIn() && request.auth.uid in resource.data.participantUids && (request.resource.data.diff(resource.data).affectedKeys().hasOnly(["messages", "events", "updatedAt"]) || (request.auth.uid == resource.data.menteeId && request.resource.data.diff(resource.data).affectedKeys().hasOnly(["permissions", "events", "updatedAt"])) || (request.resource.data.status == "closed" && request.resource.data.diff(resource.data).affectedKeys().hasOnly(["status", "permissions", "updatedAt"]))); allow delete: if false; }\n    '''
    if marker not in rules: raise SystemExit("Refusing to patch Firestore rules: default deny marker not found")
    rules=rules.replace(marker,block+marker,1)
    rules_path.write_text(rules,encoding="utf-8")
